SELECT s.driver_id, s.finish_position AS sprint_position, r.finish_position AS race_position
FROM sprint_results s JOIN results r ON r.round = s.round AND r.driver_id = s.driver_id
WHERE s.round = 9;

WITH cnt AS (
  SELECT o.region, o.office_id, o.office_name, COUNT(*) AS alert_count
  FROM alerts a JOIN offices o ON o.office_id = a.office_id
  GROUP BY o.region, o.office_id, o.office_name
), rk AS (
  SELECT *, RANK() OVER (PARTITION BY region ORDER BY alert_count DESC) AS r FROM cnt
)
SELECT region, office_id, office_name, alert_count FROM rk WHERE r = 1 ORDER BY region, office_id;
